/** Байты документа-образца по имени. */
export function documentBytes(name) {
  if (!FILES[name]) throw new Error(`нет образца «${name}»`);
  return new Uint8Array(Buffer.from(FILES[name].replace(/\s+/gu, ""), "base64"));
}
export const DOCUMENT_NAMES = Object.freeze(Object.keys(FILES));
